"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[8348],{78270:(e,t,o)=>{o.r(t),o.d(t,{default:()=>a});o(96540);var n=o(75048),r=o(74848);function a(){return(0,r.jsx)(n.A,{title:"Feature Zero Allocation",children:(0,r.jsx)("div",{className:"legacy-mars",children:(0,r.jsx)("div",{dangerouslySetInnerHTML:{__html:'\n\n\n\n<main class="container" style="padding-top: 100px; padding-bottom: 80px;">\n  <div style="text-align: center; margin-bottom: 40px;">\n    <a href="/MARSLib/#features" class="back-link">\u2190 BACK TO FEATURES</a>\n    <h1>Zero-Allocation Hot Path</h1>\n  </div>\n  \n  <div class="card" style="background: var(--bg-card); border: 1px solid var(--border); padding: 30px; border-radius: 12px; margin-top: 30px;">\n    <h2 style="font-family: \'Orbitron\', sans-serif; color: var(--mars-red-light); margin-bottom: 20px; font-size: 1.8rem; margin-top: 0;">Why Zero-Allocation?</h2>\n    <p style="margin-bottom: 16px; color: var(--text-secondary); font-size: 1.1rem;">In the high-stakes environment of FIRST Robotics Competition matches, control loop consistency is critical. The RoboRIO\'s JVM garbage collector (GC) can cause non-deterministic pauses\u2014sometimes lasting upwards of 10-20ms. In a 20ms control loop, a single GC pause can result in skipped loops, jittery odometry, and missed shots.</p>\n    \n    <h2 style="font-family: \'Orbitron\', sans-serif; color: var(--mars-red-light); margin-bottom: 20px; font-size: 1.8rem; margin-top: 40px;">MARSLib\'s Approach</h2>\n    <p style="margin-bottom: 16px; color: var(--text-secondary); font-size: 1.1rem;">MARSLib enforces strict zero-allocation rules on the hot path (the 20ms robot loop and critical subsystems). We achieve this through:</p>\n    <ul style="margin-bottom: 20px; padding-left: 20px; color: var(--text-secondary); font-size: 1.1rem;">\n      <li style="margin-bottom: 10px;"><strong>Pre-allocated Buffers:</strong> Odometry arrays, pose arrays for AdvantageKit, and state containers are instantiated once during <code>robotInit()</code>. We never use <code>new</code> within a periodic function.</li>\n      <li style="margin-bottom: 10px;"><strong>Static Velocity & Pose Constants:</strong> Heavy objects like <code>Transform3d</code> or <code>Rotation2d</code> are cached where possible rather than dynamically generated every tick.</li>\n      <li style="margin-bottom: 10px;"><strong>Mutating Existing Objects:</strong> Instead of creating new arrays to pass data, we mutate pre-defined structured objects inside the hardware IO layers.</li>\n      <li style="margin-bottom: 10px;"><strong>No Magic Math Boxing:</strong> Using primitive <code>double</code> variables everywhere. Avoiding accidental `Double` wrapper boxing that causes hidden garbage collection pressure.</li>\n    </ul>\n\n    <h2 style="font-family: \'Orbitron\', sans-serif; color: var(--mars-red-light); margin-bottom: 20px; font-size: 1.8rem; margin-top: 40px;">Impact on Performance</h2>\n    <p style="margin-bottom: 16px; color: var(--text-secondary); font-size: 1.1rem;">By keeping the GC idle during the teleoperated and autonomous routines, MARSLib ensures the robot maneuvers accurately and predictably, even during complex trajectories and rapid swerve module steering.</p>\n  </div>\n</main>\n\n\n\n\n'}})})})}}}]);